/* Fix: WPBakery scroll-triggered fade-in animations getting stuck at opacity:0, causing empty-looking gaps between sections */
.wpb_animate_when_almost_visible {
	opacity: 1 !important;
	animation: none !important;
	-webkit-animation: none !important;
	transform: none !important;
}

/* Fix: Warranty page "What Voids the Warranty" cards showing light pink background with dark theme */
.listBg ul li {
	background: rgba(21, 21, 26, 0.98) !important;
	border: 0.8px solid rgba(220, 53, 69, 0.25) !important;
}
.listBg ul li .wd-list-content,
.listBg ul li .list-content {
	color: #ffffff !important;
}
.listBg ul li .wd-list-content span,
.listBg ul li .list-content span {
	color: rgba(255, 255, 255, 0.65) !important;
}



